/** @param {{des: object}} api */
export default function bigrm_4({ des, selection, math, luaList, luaLen }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`-----------                                                     -----------
|.........|                                                     |.........|
|.........-------------                             -------------.........|
---...................------------       ------------...................---
  --.............................---------.............................--  
   --.................................................................--   
    --...............................................................--    
     --......LLLLL.......................................LLLLL......--     
      --.....LLLLL.......................................LLLLL.....--      
      --.....LLLLL.......................................LLLLL.....--      
     --......LLLLL.......................................LLLLL......--     
    --...............................................................--    
   --.................................................................--   
  --.............................---------.............................--  
---...................------------       ------------...................---
|.........-------------                             -------------.........|
|.........|                                                     |.........|
-----------                                                     -----------
`);

    // luaList keeps Lua's 1-based indices, so terrains[n] means the same here.
    const terrains = luaList('.', '.', '.', '.', 'P', 'L', '-', 'T', 'W', 'Z');
    const tidx = math.random(1, luaLen(terrains));
    const toterr = terrains[tidx];
    if (toterr !== 'L') {
        des.replace_terrain({ fromterrain: 'L', toterrain: toterr });
    }

    des.feature('fountain', 5, 2);
    des.feature('fountain', 5, 15);
    des.feature('fountain', 69, 2);
    des.feature('fountain', 69, 15);

    des.region(selection.area(1, 1, 73, 16), 'lit');

    des.stair('up');
    des.stair('down');

    des.non_diggable();

    for (let i = 1; i <= 15; i++) {
        des.object();
    }

    for (let i = 1; i <= 6; i++) {
        des.trap();
    }

    for (let i = 1; i <= 28; i++) {
        des.monster();
    }
}
